// Adds the permissions and tablet settings InterviewPro needs to the native
// projects generated by `npx cap add android|ios`. Safe to run repeatedly.
import { readFile, writeFile, access } from 'node:fs/promises';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');

export const ANDROID_PERMISSIONS = [
  'android.permission.INTERNET',
  'android.permission.CAMERA',
  'android.permission.RECORD_AUDIO',
  'android.permission.MODIFY_AUDIO_SETTINGS',
];

export const IOS_KEYS = {
  NSCameraUsageDescription: 'InterviewPro shows your camera so you can practise interviews face to face. Video stays on your device.',
  NSMicrophoneUsageDescription: 'InterviewPro listens to your spoken answers so it can transcribe and score them on your device.',
  NSSpeechRecognitionUsageDescription: 'InterviewPro converts your spoken answers to text so they can be scored.',
};

export function patchAndroidManifest(xml) {
  let out = xml;
  const adds = [];
  for (const p of ANDROID_PERMISSIONS) {
    if (!out.includes(`android:name="${p}"`)) adds.push(`    <uses-permission android:name="${p}" />`);
  }
  if (!out.includes('android.hardware.camera"')) adds.push('    <uses-feature android:name="android.hardware.camera" android:required="false" />');
  if (!out.includes('android.hardware.microphone"')) adds.push('    <uses-feature android:name="android.hardware.microphone" android:required="false" />');
  if (!out.includes('android.speech.RecognitionService')) {
    adds.push([
      '    <queries>',
      '        <intent><action android:name="android.speech.RecognitionService" /></intent>',
      '        <intent><action android:name="android.intent.action.TTS_SERVICE" /></intent>',
      '    </queries>',
    ].join('\n'));
  }
  if (adds.length) {
    if (!out.includes('</manifest>')) throw new Error('AndroidManifest.xml: </manifest> not found');
    out = out.replace(/\n?<\/manifest>\s*$/, `\n${adds.join('\n')}\n</manifest>\n`);
  }
  return out;
}

function plistHasKey(xml, key) { return xml.includes(`<key>${key}</key>`); }
const escXml = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;');

export function patchInfoPlist(xml) {
  let out = xml;
  const adds = [];
  for (const [k, v] of Object.entries(IOS_KEYS)) {
    if (!plistHasKey(out, k)) adds.push(`\t<key>${k}</key>\n\t<string>${escXml(v)}</string>`);
  }
  if (!plistHasKey(out, 'UISupportedInterfaceOrientations~ipad')) {
    adds.push('\t<key>UISupportedInterfaceOrientations~ipad</key>\n\t<array>\n\t\t<string>UIInterfaceOrientationPortrait</string>\n\t\t<string>UIInterfaceOrientationPortraitUpsideDown</string>\n\t\t<string>UIInterfaceOrientationLandscapeLeft</string>\n\t\t<string>UIInterfaceOrientationLandscapeRight</string>\n\t</array>');
  }
  if (!plistHasKey(out, 'UIRequiresFullScreen')) adds.push('\t<key>UIRequiresFullScreen</key>\n\t<false/>');
  if (adds.length) {
    const idx = out.lastIndexOf('</dict>');
    if (idx === -1) throw new Error('Info.plist: </dict> not found');
    out = out.slice(0, idx) + adds.join('\n') + '\n' + out.slice(idx);
  }
  return out;
}

async function exists(p) { try { await access(p); return true; } catch { return false; } }

async function main() {
  const manifest = join(root, 'android/app/src/main/AndroidManifest.xml');
  const plist = join(root, 'ios/App/App/Info.plist');
  let did = false;
  if (await exists(manifest)) {
    await writeFile(manifest, patchAndroidManifest(await readFile(manifest, 'utf8')));
    console.log('✓ Android: camera, microphone, speech and TTS permissions added');
    did = true;
  }
  if (await exists(plist)) {
    await writeFile(plist, patchInfoPlist(await readFile(plist, 'utf8')));
    console.log('✓ iOS: camera, microphone, speech usage descriptions + iPad orientations added');
    did = true;
  }
  if (!did) console.log('No native projects found. Run `npx cap add android` / `npx cap add ios` first.');
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) main();
